public class ChiSquareTestImplTest{
@Rule
    public ExpectedException exception = ExpectedException.none();

    private ChiSquareTestImpl chiSquareTestImpl;
    private ChiSquaredDistribution chiSquaredDistribution;

    @Before
    public void before(){
        chiSquaredDistribution = mock(ChiSquaredDistribution.class);
        chiSquareTestImpl = new ChiSquareTestImpl(chiSquaredDistribution);
    }

    @Test
    public void testChiSquare_Long2DArray_NoException() throws Exception {
        long[][] counts = {{1, 2}, {3, 4}};
        Assert.assertNotNull(chiSquareTestImpl.chiSquare(counts));
    }

    @Test
    public void testChiSquare_Long2DArray_RectangularArray_NoException() throws Exception {
        long[][] counts = {{1, 2, 3}, {4, 5, 6}};
        Assert.assertNotNull(chiSquareTestImpl.chiSquare(counts));
    }

    @Test
    public void testChiSquare_Long2DArray_EmptyArray_Exception() throws Exception {
        exception.expect(IllegalArgumentException.class);
        long[][] counts = {};
        chiSquareTestImpl.chiSquare(counts);
    }

    @Test
    public void testChiSquare_Long2DArray_NullArray_Exception() throws Exception {
        exception.expect(NullPointerException.class);
        long[][] counts = null;
        chiSquareTestImpl.chiSquare(counts);
    }

    @Test
    public void testChiSquare_Long2DArray_ZeroArray_Exception() throws Exception {
        exception.expect(IllegalArgumentException.class);
        long[][] counts = {{0, 0}, {0, 0}};
        chiSquareTestImpl.chiSquare(counts);
    }

    @Test
    public void testChiSquare_Long2DArray_EmptyRowArray_Exception() throws Exception {
        exception.expect(IllegalArgumentException.class);
        long[][] counts = {{1, 2}, {}};
        chiSquareTestImpl.chiSquare(counts);
    }

    @Test
    public void testChiSquare_Long2DArray_EmptyColArray_Exception() throws Exception {
        exception.expect(IllegalArgumentException.class);
        long[][] counts = {{}, {1, 2}};
        chiSquareTestImpl.chiSquare(counts);
    }

    @Test
    public void testChiSquare_Long2DArray_NonRectangularArray_Exception() throws Exception {
        exception.expect(IllegalArgumentException.class);
        long[][] counts = {{1, 2}, {3}};
        chiSquareTestImpl.chiSquare(counts);
    }

    @Test
    public void testChiSquare_Long2DArray_NegativeArray_Exception() throws Exception {
        exception.expect(IllegalArgumentException.class);
        long[][] counts = {{-1, 2}, {3, 4}};
        chiSquareTestImpl.chiSquare(counts);
    }

    @Test
    public void testChiSquare_Long2DArray_ChiSquareDistribution() throws Exception {
        long[][] counts = {{10, 10}, {10, 10}};
        double result = chiSquareTestImpl.chiSquare(counts);
        Assert.assertNotNull(result);
    }

    @Test
    public void testChiSquareTest_Long2DArray_NoException() throws Exception {
        long[][] counts = {{1, 2}, {3, 4}};
        Assert.assertNotNull(chiSquareTestImpl.chiSquareTest(counts));
    }

    @Test
    public void testChiSquareTest_Long2DArray_ChiSquareTest() throws Exception {
        long[][] counts = {{10, 10}, {10, 10}};
        double result = chiSquareTestImpl.chiSquareTest(counts);
        Assert.assertNotNull(result);
    }

    @Test
    public void testChiSquareTest_Long2DArray_Alpha_NoException() throws Exception {
        long[][] counts = {{1, 2}, {3, 4}};
        Assert.assertNotNull(chiSquareTestImpl.chiSquareTest(counts, 0.05));
    }

    @Test
    public void testChiSquareTest_Long2DArray_Alpha_ChiSquareTest() throws Exception {
        long[][] counts = {{10, 10}, {10, 10}};
        boolean result = chiSquareTestImpl.chiSquareTest(counts, 0.05);
        Assert.assertNotNull(result);
    }
}
