import org.junit.Rule;
import org.junit.rules.ExpectedException;
import org.mockito.Mockito.*
import static org.hamcrest.MatcherAssert.assertThat;
import static org.hamcrest.Matchers.*;
import org.apache.commons.math3.exception.NumberIsTooLargeException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.random.RandomGenerator;
import org.apache.commons.math3.random.Well19937c;

public class UniformRealDistributionTest{
@Rule
    public ExpectedException expectedEx = ExpectedException.none();

    private UniformRealDistribution instance;

    @Before
    public void setUp(){
        instance = new UniformRealDistribution();
    }

    @After
    public void tearDown(){
        instance = null;
    }

    @Test
    public void testIsSupportUpperBoundInclusive(){
        boolean result = instance.isSupportUpperBoundInclusive();
        Assert.assertTrue(result);
    }

    @Test
    public void testConstructorLowerUpper()throws Exception{
        double lower = 10;
        double upper = 20;
        instance = new UniformRealDistribution(lower, upper);
        Assert.assertEquals(lower, instance.getSupportLowerBound(), 0.0);
        Assert.assertEquals(upper, instance.getSupportUpperBound(), 0.0);
    }

    @Test
    public void testConstructorLowerUpperThrows()throws Exception{
        double lower = 10;
        double upper = 5;
        expectedEx.expect(NumberIsTooLargeException.class);
        expectedEx.expectMessage(LocalizedFormats.LOWER_BOUND_NOT_BELOW_UPPER_BOUND.toString());
        instance = new UniformRealDistribution(lower, upper);
    }

    @Test
    public void testConstructorLowerUpperInverse()throws Exception{
        double lower = 10;
        double upper = 20;
        double inverse = 1e-5;
        instance = new UniformRealDistribution(lower, upper, inverse);
        Assert.assertEquals(lower, instance.getSupportLowerBound(), 0.0);
        Assert.assertEquals(upper, instance.getSupportUpperBound(), 0.0);
        Assert.assertEquals(inverse, instance.getSolverAbsoluteAccuracy(), 0.0);
    }

    @Test
    public void testConstructorRngLowerUpperInverse()throws Exception{
        double lower = 10;
        double upper = 20;
        double inverse = 1e-5;
        RandomGenerator rng = mock(RandomGenerator.class);
        instance = new UniformRealDistribution(rng, lower, upper, inverse);
        Assert.assertEquals(lower, instance.getSupportLowerBound(), 0.0);
        Assert.assertEquals(upper, instance.getSupportUpperBound(), 0.0);
        Assert.assertEquals(inverse, instance.getSolverAbsoluteAccuracy(), 0.0);
    }

    @Test
    public void testDensity(){
        double x = 5;
        double density = instance.density(x);
        if(x < instance.getSupportLowerBound() || x > instance.getSupportUpperBound()){
            Assert.assertEquals(0, density, 0.0);
        }else{
            Assert.assertNotEquals(0, density, 0.0);
        }
    }

    @Test
    public void testCumulativeProbability(){
        double x = 5;
        double probability = instance.cumulativeProbability(x);
        if(x < instance.getSupportLowerBound()){
            Assert.assertEquals(0, probability, 0.0);
        }else if(x > instance.getSupportUpperBound()){
            Assert.assertEquals(1, probability, 0.0);
        }else{
            Assert.assertTrue(probability > 0 && probability < 1);
        }
    }

    @Test
    public void testGetSolverAbsoluteAccuracy(){
        double accuracy = instance.getSolverAbsoluteAccuracy();
        Assert.assertEquals(UniformRealDistribution.DEFAULT_INVERSE_ABSOLUTE_ACCURACY, accuracy, 0.0);
    }

    @Test
    public void testGetNumericalMean(){
        double mean = instance.getNumericalMean();
        Assert.assertEquals((instance.getSupportLowerBound() + instance.getSupportUpperBound())/2, mean, 0.0);
    }

    @Test
    public void testGetNumericalVariance(){
        double variance = instance.getNumericalVariance();
        Assert.assertEquals(Math.pow(instance.getSupportUpperBound() - instance.getSupportLowerBound(), 2)/12, variance, 0.0);
    }

    @Test
    public void testGetSupportLowerBound(){
        double lower = instance.getSupportLowerBound();
        Assert.assertEquals(instance.lower, lower, 0.0);
    }

    @Test
    public void testGetSupportUpperBound(){
        double upper = instance.getSupportUpperBound();
        Assert.assertEquals(instance.upper, upper, 0.0);
    }

    @Test
    public void testIsSupportLowerBoundInclusive(){
        boolean inclusive = instance.isSupportLowerBoundInclusive();
        Assert.assertTrue(inclusive);
    }

    @Test
    public void testIsSupportConnected(){
        boolean connected = instance.isSupportConnected();
        Assert.assertTrue(connected);
    }

    @Test
    public void testSample(){
        double sample = instance.sample();
        Assert.assertTrue(sample >= instance.getSupportLowerBound() && sample <= instance.getSupportUpperBound());
    }
}
