    public void testEbeMultiply_NormalVector(){
        OpenMapRealVector vector1 = new OpenMapRealVector(new double[]{1,2,3});
        OpenMapRealVector vector2 = new OpenMapRealVector(new double[]{4,5,6});

        OpenMapRealVector result = vector1.ebeMultiply(vector2);

        assertEquals(4, result.getEntry(0), 1e-9);
        assertEquals(10, result.getEntry(1), 1e-9);
        assertEquals(18, result.getEntry(2), 1e-9);
    }

    @Test
    public void testEbeMultiply_NaN(){
        OpenMapRealVector vector1 = new OpenMapRealVector(new double[]{1,2,3});
        OpenMapRealVector vector2 = new OpenMapRealVector(new double[]{Double.NaN,5,6});

        OpenMapRealVector result = vector1.ebeMultiply(vector2);

        assertTrue(Double.isNaN(result.getEntry(0)));
        assertEquals(10, result.getEntry(1), 1e-9);
        assertEquals(18, result.getEntry(2), 1e-9);
    }

    @Test
    public void testEbeMultiply_Infinity(){
