    public void testHypergeometricDistribution_Constructor_SAMPLE_SIZE_LESS_THAN_ZERO() throws Exception {
        expectedException.expect(NotPositiveException.class);
        expectedException.expectMessage(LocalizedFormats.NUMBER_OF_SAMPLES);
        hypergeometricDistribution = new HypergeometricDistribution(100, 10, -20);
    }

