        hypergeometricDistribution = new HypergeometricDistribution(100, 10, 110);
    }

    @Test
    public void testHypergeometricDistribution_getNumericalMean() throws Exception {
        hypergeometricDistribution = new HypergeometricDistribution(100, 10, 20);
        double mean = hypergeometricDistribution.getNumericalMean();
        assertEquals(2.0, mean, 1e-12);
    }

