    public void testHypergeometricDistribution_getPopulationSize() throws Exception {
        hypergeometricDistribution = new HypergeometricDistribution(100, 10, 20);
        assertEquals(100, hypergeometricDistribution.getPopulationSize());
    }

    @Test
    public void testHypergeometricDistribution_getNumberOfSuccesses() throws Exception {
        hypergeometricDistribution = new HypergeometricDistribution(100, 10, 20);
        assertEquals(10, hypergeometricDistribution.getNumberOfSuccesses());
    }

    @Test
    public void testHypergeometricDistribution_getSampleSize() throws Exception {
        hypergeometricDistribution = new HypergeometricDistribution(100, 10, 20);
        assertEquals(20, hypergeometricDistribution.getSampleSize());
    }
}
