import org.apache.commons.math.util.MathUtils;

public class VarianceTest{
private Variance instance;

    @Before
    public void setUp() {
        instance = new Variance();
    }

    @After
    public void tearDown() {
        instance = null;
    }

    @Test
    public void testEvaluate() {
        double[] values = { 1, 2, 3, 4 };
        double[] weights = { 1, 1, 1, 1 };
        double result = instance.evaluate(values, weights, 0, 4);
        assertEquals(1.6666666666666667, result, 1.0e-12);
    }

    @Test
    public void testEvaluate1() {
        double[] values = { 1, 2, 3, 4 };
        double result = instance.evaluate(values);
        assertEquals(1.6666666666666667, result, 1.0e-12);
    }

    @Test
    public void testEvaluate2() {
        double[] values = { 1, 2, 3, 4 };
        double result = instance.evaluate(values, 0, 4);
        assertEquals(1.6666666666666667, result, 1.0e-12);
    }

    @Test
    public void testEvaluate3() {
        double[] values = { 1, 2, 3, 4 };
        double[] weights = { 1, 1, 1, 1 };
        double result = instance.evaluate(values, weights);
        assertEquals(1.6666666666666667, result, 1.0e-12);
    }

    @Test
    public void testEvaluate4() {
        double[] values = { 1 };
        double[] weights = { 1 };
        double result = instance.evaluate(values, weights, 0, 1);
        assertEquals(0.0, result, 1.0e-12);
    }

    @Test
    public void testEvaluate5() {
        double[] values = { };
        double[] weights = { };
        double result = instance.evaluate(values, weights, 0, 0);
        assertTrue(Double.isNaN(result));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testEvaluate6() {
        double[] values = { 1, 2, 3 };
        double[] weights = { 1, 1 };
        instance.evaluate(values, weights, 0, 2);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testEvaluate7() {
        double[] values = { };
        double[] weights = { 1 };
        instance.evaluate(values, weights, 0, 1);
    }

    @Test
    public void testGetResult() {
        instance.increment(1.0);
        assertEquals(0.0, instance.getResult(), 1.0e-12);
    }

    @Test
    public void testGetN() {
        instance.increment(1.0);
        assertEquals(1, instance.getN());
    }

    @Test
    public void testClear() {
        instance.increment(1.0);
        instance.clear();
        assertEquals(0.0, instance.getResult(), 1.0e-12);
    }

    @Test
    public void testIsBiasCorrected() {
        Variance variance = new Variance(true);
        assertTrue(variance.isBiasCorrected());
        variance = new Variance(false);
        assertFalse(variance.isBiasCorrected());
    }

    @Test
    public void testSetBiasCorrected() {
        Variance variance = new Variance();
        variance.setBiasCorrected(false);
        assertFalse(variance.isBiasCorrected());
    }

    @Test
    public void testCopy() {
        Variance original = new Variance();
        original.increment(1.0);
        Variance copy = original.copy();
        assertEquals(original.getResult(), copy.getResult(), 1.0e-12);
    }

    @Test
    public void testStaticCopy() {
        Variance original = new Variance();
        original.increment(1.0);
        Variance copy = new Variance();
        Variance.copy(original, copy);
        assertEquals(original.getResult(), copy.getResult(), 1.0e-12);
    }

    @Test(expected = NullArgumentException.class)
    public void testStaticCopyNullSource() {
        Variance.copy(null, new Variance());
    }

    @Test(expected = NullArgumentException.class)
    public void testStaticCopyNullDest() {
        Variance.copy(new Variance(), null);
    }
}
