import org.junit.rules.ExpectedException;
import org.mockito.Mockito.*
import static org.hamcrest.MatcherAssert.assertThat;
import static org.hamcrest.Matchers.*;
import java.io.Serializable;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.stat.descriptive.WeightedEvaluation;
import org.apache.commons.math.stat.descriptive.AbstractStorelessUnivariateStatistic;
import org.apache.commons.math.util.MathUtils;

public class VarianceTest{
private Variance variance;

    @Before
    public void setUp() {
        variance = new Variance();
    }

    @Test
    public void testEvaluate() {
        double[] values = {1, 2, 3, 4, 5};
        double[] weights = {1, 1, 1, 1, 1};
        assertEquals(2.0, variance.evaluate(values, weights), 1.0e-12);
    }

    @Test
    public void testEvaluate_NonBiased() {
        double[] values = {1, 2, 3, 4, 5};
        double[] weights = {1, 1, 1, 1, 1};
        Variance nonBiasedVariance = new Variance(false);
        assertEquals(2.5, nonBiasedVariance.evaluate(values, weights), 1.0e-12);
    }

    @Test
    public void testEvaluate_EmptyArray() {
        double[] values = {};
        double[] weights = {};
        assertEquals(Double.NaN, variance.evaluate(values, weights), 1.0e-12);
    }

    @Test(expected = NullArgumentException.class)
    public void testEvaluate_NullValues() {
        double[] values = null;
        double[] weights = {1, 1, 1};
        variance.evaluate(values, weights);
    }

    @Test(expected = NullArgumentException.class)
    public void testEvaluate_NullWeights() {
        double[] values = {1, 2, 3};
        double[] weights = null;
        variance.evaluate(values, weights);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testEvaluate_WeightsLengthMismatch() {
        double[] values = {1, 2, 3};
        double[] weights = {1, 1};
        variance.evaluate(values, weights);
    }

    @Test
    public void testEvaluate_SingleElement() {
        double[] values = {5};
        double[] weights = {1};
        assertEquals(0.0, variance.evaluate(values, weights), 1.0e-12);
    }

    @Test
    public void testEvaluate_AllElementsTheSame() {
        double[] values = {5, 5, 5};
        double[] weights = {1, 1, 1};
        assertEquals(0.0, variance.evaluate(values, weights), 1.0e-12);
    }

    @Test
    public void testIsBiasCorrected() {
        assertTrue(variance.isBiasCorrected());
        variance.setBiasCorrected(false);
        assertFalse(variance.isBiasCorrected());
    }
}
