        Assert.assertEquals(2.5, variance.evaluate(values), 0.01);
    }

    @Test
    public void testEvaluate_Array_Mean() {
        double[] values = { 1, 2, 3, 4, 5 };
        double mean = 3;
        Assert.assertEquals(2.0, variance.evaluate(values, mean), 0.01);
    }

    @Test
    public void testEvaluate_Array_Begin_Length() {
        double[] values = { 1, 2, 3, 4, 5 };
