import org.apache.commons.math.util.MathUtils;

public class VarianceTest{
private Variance instance;
    @Before
    public void setUp() throws Exception {
        instance = new Variance();
    }
    @After
    public void tearDown() throws Exception {
    }
    @Test
    public void testEvaluate() throws Exception {
        double[] values = { 1, 2, 3 };
        double[] weights = { 1, 1, 1 };
        double mean = 2;
        double result = instance.evaluate(values, weights, mean);
        assertEquals(1.0, result, 0.01);
    }
    @Test
    public void testEvaluate_DifferentLength() throws Exception {
        double[] values = { 1, 2, 3, 4 };
        double[] weights = { 1, 1, 1 };
        double mean = 2.5;
        try {
            instance.evaluate(values, weights, mean);
            fail("Expecting NullArgumentException");
        } catch (IllegalArgumentException e) {
            assertThat(e.getMessage(), containsString(LocalizedFormats.LENGTHS_MISMATCH.format(values.length, weights.length).getLocalizedMessage()));
        }
    }
    @Test
    public void testEvaluate_NullValues() throws Exception {
        double[] values = null;
        double[] weights = { 1, 1, 1 };
        double mean = 2;
        try {
            instance.evaluate(values, weights, mean);
            fail("Expecting NullArgumentException");
        } catch (NullArgumentException e) {
            // expected
        }
    }
    @Test
    public void testEvaluate_NullWeights() throws Exception {
        double[] values = { 1, 2, 3 };
        double[] weights = null;
        double mean = 2;
        try {
            instance.evaluate(values, weights, mean);
            fail("Expecting NullArgumentException");
        } catch (NullArgumentException e) {
            // expected
        }
    }
    @Test
    public void testEvaluate_WeightsSumToZero() throws Exception {
        double[] values = { 1, 2, 3 };
        double[] weights = { 0, 0, 0 };
        double mean = 2;
        try {
            instance.evaluate(values, weights, mean);
            fail("Expecting IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertThat(e.getMessage(), containsString("The sum of weights is zero"));
        }
    }
    @Test
    public void testEvaluate_WeightsSumToNegative() throws Exception {
        double[] values = { 1, 2, 3 };
        double[] weights = { -1, -1, -1 };
        double mean = 2;
        try {
            instance.evaluate(values, weights, mean);
            fail("Expecting IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertThat(e.getMessage(), containsString("The sum of weights is negative"));
        }
    }
}
