public class DfpTest{
DfpField field;
    @Before
    public void init(){
        field = new DfpField(10000);
    }

    @Test
    public void testToDouble_Infinite(){
        Dfp dfp = new Dfp(field);
        dfp.nans = Dfp.INFINITE;
        dfp.sign = 1;
        assertEquals(Double.POSITIVE_INFINITY, dfp.toDouble(), 0);

        dfp.sign = -1;
        assertEquals(Double.NEGATIVE_INFINITY, dfp.toDouble(), 0);
    }

    @Test
    public void testToDouble_NaN(){
        Dfp dfp = new Dfp(field);
        dfp.nans = Dfp.QNAN;
        assertEquals(Double.NaN, dfp.toDouble(), 0);
    }

    @Test
    public void testToDouble_Zero(){
        Dfp dfp = new Dfp(field, 0);
        assertEquals(0, dfp.toDouble(), 0);

        dfp.sign = -1;
        assertEquals(-0.0, dfp.toDouble(), 0);
    }

    @Test
    public void testToDouble_Normal(){
        Dfp dfp = new Dfp(field, 1.5);
        assertEquals(1.5, dfp.toDouble(), 0.00001);

        dfp = new Dfp(field, -1.5);
        assertEquals(-1.5, dfp.toDouble(), 0.00001);
    }

    @Test
    public void testToDouble_Subnormal(){
        Dfp dfp = new Dfp(field, 1e-324);
        assertNotEquals(Double.NaN, dfp.toDouble(), 0);
    }

    @Test
    public void testToDouble_Overflow(){
        Dfp dfp = new Dfp(field);
        dfp.exp = 32768;
        assertEquals(Double.POSITIVE_INFINITY, dfp.toDouble(), 0);

        dfp.sign = -1;
        assertEquals(Double.NEGATIVE_INFINITY, dfp.toDouble(), 0);
    }

    @Test
    public void testToDouble_Min(){
        Dfp dfp = new Dfp(field, Long.MIN_VALUE);
        assertNotEquals(Double.NaN, dfp.toDouble(), 0);
    }
}
