import org.apache.commons.math.special.Erf;
import org.apache.commons.math.util.FastMath;

public class NormalDistributionImplTest{
private NormalDistributionImpl normalDistribution;

    @Before 
    public void before(){
        normalDistribution = new NormalDistributionImpl(0, 1);
    }

    @After 
    public void after(){
        normalDistribution = null;
    }

    @Test
    public void testCumulativeProbability_OutOfRange_LowerBound() throws Exception {
        double x = -Double.MAX_VALUE;
        double result = normalDistribution.cumulativeProbability(x);
        assertEquals(0.0, result, 1e-9);
    }

    @Test
    public void testCumulativeProbability_OutOfRange_UpperBound() throws Exception {
        double x = Double.MAX_VALUE;
        double result = normalDistribution.cumulativeProbability(x);
        assertEquals(1.0, result, 1e-9);
    }

    @Test
    public void testCumulativeProbability_InRange() throws Exception {
        double x = 0.0;
        double result = normalDistribution.cumulativeProbability(x);
        assertEquals(0.5, result, 1e-9);
    }

    @Test
    public void testCumulativeProbability_NearZero() throws Exception {
        double x = 1e-9;
        double result = normalDistribution.cumulativeProbability(x);
        assertEquals(0.5 + 0.5 * Erf.erf(1e-9 / (Math.sqrt(2))), result, 1e-9);
    }

    @Test
    public void testCumulativeProbability_SD_40() throws Exception {
        double mean = 0;
        double sd = 1;
        double x = mean - 40 * sd;
        NormalDistributionImpl dist = new NormalDistributionImpl(mean, sd);
        double result = dist.cumulativeProbability(x);
        assertEquals(0.0, result, 1e-9);
    }

    @Test
    public void testCumulativeProbability_SD40() throws Exception {
        double mean = 0;
        double sd = 1;
        double x = mean + 40 * sd;
        NormalDistributionImpl dist = new NormalDistributionImpl(mean, sd);
        double result = dist.cumulativeProbability(x);
        assertEquals(1.0, result, 1e-9);
    }
} 
