public class BrentSolverTest{
private BrentSolver solver;
    private UnivariateRealFunction f;

    @Before
    public void setUp(){
        f = mock(UnivariateRealFunction.class);
        when(f.value(1)).thenReturn(1.0);
        when(f.value(-1)).thenReturn(-1.0);
        solver = new BrentSolver();
    }

    @Test(expected = NullPointerException.class)
    public void testSolveWithNullFunction() throws Exception{
        solver.solve(null, -1, 1, 0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testSolveWithInvalidInterval() throws Exception{
        solver.solve(f, 1, -1, 0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testSolveWithEqualIntervalBounds() throws Exception{
        solver.solve(f, 1, 1, 0);
    }

    @Test
    public void testSolveWithValidInterval() throws Exception{
        double result = solver.solve(f, -1, 1, 0);
        assertThat(result, closeTo(0, 1e-6));
    }

    @Test(expected = MaxIterationsExceededException.class)
    public void testSolveMaxIterationsExceeded() throws Exception{
        solver = new BrentSolver(f){
            @Override
            protected double solve(UnivariateRealFunction f, double min, double max) throws MaxIterationsExceededException, FunctionEvaluationException {
                throw new MaxIterationsExceededException(1);
            }
        };
        solver.solve(f, -1, 1);
    }

    @Test(expected = FunctionEvaluationException.class)
    public void testSolveFunctionEvaluationException() throws Exception{
        solver = new BrentSolver(f){
            @Override
            protected double solve(UnivariateRealFunction f, double min, double max) throws MaxIterationsExceededException, FunctionEvaluationException {
                throw new FunctionEvaluationException(1, "test");
            }
        };
        solver.solve(f, -1, 1);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testSolveNoBracketing() throws Exception{
        when(f.value(1)).thenReturn(1.0);
        when(f.value(-1)).thenReturn(1.0);
        solver.solve(f, -1, 1);
    }
}
