public class FrequencyTest{
private Frequency frequency;
    @Before
    public void setup(){
        frequency = new Frequency();
    }

    @After
    public void teardown(){
        frequency.clear();
    }

    @Test
    public void testGetPct_Int(){
        frequency.addValue(1);
        frequency.addValue(2);
        Assert.assertEquals(0.5, frequency.getPct(1), 0.00001);
    }

    @Test
    public void testGetPct_Int_Not_Exists(){
        Assert.assertEquals(0.0, frequency.getPct(1), 0.00001);
    }

    @Test
    public void testGetPct_Zero_Frequency(){
        frequency.addValue(1);
        frequency.addValue(2);
        frequency.addValue(3);
        Assert.assertEquals(0.0, frequency.getPct(4), 0.00001);
    }

    @Test
    public void testGetPct_Multiple_Occurrences(){
        frequency.addValue(1);
        frequency.addValue(1);
        frequency.addValue(2);
        Assert.assertEquals(0.6666666667, frequency.getPct(1), 0.00001);
    }

    @Test
    public void testGetPct_Zero_Value(){
        frequency.addValue(0);
        frequency.addValue(2);
        Assert.assertEquals(0.5, frequency.getPct(0), 0.00001);
    }

    @Test
    public void testGetPct_Negative_Value(){
        frequency.addValue(-1);
        frequency.addValue(2);
        Assert.assertEquals(0.3333333333, frequency.getPct(-1), 0.00001);
    }

    @Test
    public void testGetPct_Long(){
        frequency.addValue(1L);
        frequency.addValue(2L);
        Assert.assertEquals(0.5, frequency.getPct(1L), 0.00001);
    }

    @Test
    public void testGetPct_Comparable(){
        frequency.addValue((Comparable)1);
        frequency.addValue((Comparable)2);
        Assert.assertEquals(0.5, frequency.getPct((Comparable)1), 0.00001);
    }

    @Test
    public void testGetPct_Char(){
        frequency.addValue('a');
        frequency.addValue('b');
        Assert.assertEquals(0.5, frequency.getPct('a'), 0.00001);
    }

    @Test
    public void testGetPct_Comparator(){
        frequency = new Frequency(new Comparator<Comparable>() {
            @Override
            public int compare(Comparable o1, Comparable o2) {
                return o1.hashCode() - o2.hashCode();
            }
        });
        frequency.addValue(1);
        frequency.addValue(2);
        Assert.assertEquals(0.5, frequency.getPct(1), 0.00001);
    }

    @Test
    public void testToString(){
        frequency.addValue(1);
        frequency.addValue(2);
        Assert.assertNotNull(frequency.toString());
    }

    @Test
    public void testValuesIterator(){
        frequency.addValue(1);
        frequency.addValue(2);
        Iterator<Comparable> iterator = frequency.valuesIterator();
        Assert.assertNotNull(iterator);
        Assert.assertTrue(iterator.hasNext());
    }

    @Test
    public void testGetSumFreq(){
        frequency.addValue(1);
        frequency.addValue(2);
        Assert.assertEquals(2, frequency.getSumFreq());
    }

    @Test
    public void testGetCount(){
        frequency.addValue(1);
        frequency.addValue(2);
        Assert.assertEquals(1, frequency.getCount(1));
    }

    @Test
    public void testGetCumFreq(){
        frequency.addValue(1);
        frequency.addValue(1);
        frequency.addValue(2);
        Assert.assertEquals(2, frequency.getCumFreq(1));
    }

    @Test
    public void testGetCumPct(){
        frequency.addValue(1);
        frequency.addValue(1);
        frequency.addValue(2);
        Assert.assertEquals(0.6666666667, frequency.getCumPct(1), 0.00001);
    }

    @Test
    public void testClear(){
        frequency.addValue(1);
        frequency.addValue(2);
        frequency.clear();
        Assert.assertEquals(0, frequency.getSumFreq());
    }

    @Test
    public void testHashCode(){
        frequency.addValue(1);
        frequency.addValue(2);
        Assert.assertNotNull(frequency.hashCode());
    }

    @Test
    public void testEquals(){
        Frequency frequency2 = new Frequency();
        frequency.addValue(1);
        frequency.addValue(2);
        frequency2.addValue(1);
        frequency2.addValue(2);
        Assert.assertTrue(frequency.equals(frequency2));
    }

    @Test
    public void testEquals_False(){
        Frequency frequency2 = new Frequency();
        frequency.addValue(1);
        frequency.addValue(2);
        frequency2.addValue(1);
        Assert.assertFalse(frequency.equals(frequency2));
    }

    @Test
    public void testAddValue(){
        frequency.addValue(1);
        Assert.assertEquals(1, frequency.getCount(1));
    }
}
