public class EventStateTest{
@Rule
    public ExpectedException expectedException = ExpectedException.none();

    private EventState eventState;
    private EventHandler handler;
    private StepInterpolator interpolator;

    @Before
    public void setUp() {
        handler = mock(EventHandler.class);
        interpolator = mock(StepInterpolator.class);
        eventState = new EventState(handler, 1.0, 1.0e-6, 100);
    }

    @Test
    public void testEvaluateStepNoEvent() throws Exception {
        when(interpolator.isForward()).thenReturn(true);
        when(interpolator.getCurrentTime()).thenReturn(1.0);
        when(handler.g(anyDouble(), any())).thenReturn(1.0);
        assertFalse(eventState.evaluateStep(interpolator));
    }

    @Test
    public void testEvaluateStepEvent() throws Exception {
        when(interpolator.isForward()).thenReturn(true);
        when(interpolator.getCurrentTime()).thenReturn(1.0);
        when(handler.g(0.0, any())).thenReturn(-1.0);
        when(handler.g(1.0, any())).thenReturn(1.0);
        assertTrue(eventState.evaluateStep(interpolator));
    }

    @Test
    public void testEvaluateStepCornerCase() throws Exception {
        when(interpolator.isForward()).thenReturn(true);
        when(interpolator.getCurrentTime()).thenReturn(1.0);
        when(handler.g(0.0, any())).thenReturn(1.0);
        when(handler.g(0.25, any())).thenReturn(1.0);
        when(handler.g(0.5, any())).thenReturn(-1.0);
        assertTrue(eventState.evaluateStep(interpolator));
    }

    @Test
    public void testEvaluateStepSameEvent() throws Exception {
