public class FrequencyTest{
private Frequency frequency;

    @Before
    public void setUp(){
        frequency = new Frequency();
    }

    @Test
    public void testAddValue(){
        frequency.addValue('A');
        Assert.assertEquals(1, frequency.getCount('A'));
        Assert.assertEquals(1, frequency.getCumFreq('A'));
        Assert.assertEquals(100, frequency.getCumPct('A'), 0.01);
        Assert.assertEquals(1, frequency.getSumFreq());
    }

    @Test
    public void testAddMultipleValues(){
        frequency.addValue('A');
        frequency.addValue('A');
        frequency.addValue('B');
        Assert.assertEquals(2, frequency.getCount('A'));
        Assert.assertEquals(1, frequency.getCount('B'));
        Assert.assertEquals(3, frequency.getSumFreq());
        Assert.assertEquals(2, frequency.getCumFreq('A'));
        Assert.assertEquals(100, frequency.getCumPct('B'), 0.01);
    }

    @Test
    public void testClear(){
        frequency.addValue('A');
        frequency.addValue('B');
        frequency.clear();
        Assert.assertEquals(0, frequency.getCount('A'));
