    @Before
    public void before(){
        samples = new ArrayList<Pair<String, Double>>();
        samples.add(new Pair<String, Double>("A", 0.2));
        samples.add(new Pair<String, Double>("B", 0.3));
        samples.add(new Pair<String, Double>("C", 0.5));
    }

    @Test
    public void testDiscreteDistribution() throws Exception{
        DiscreteDistribution dd = new DiscreteDistribution(samples);
        assertNotNull(dd);
    }

    @Test
    public void testDiscreteDistributionWithRNG() throws Exception{
        RandomGenerator rng = new Well19937c();
        DiscreteDistribution dd = new DiscreteDistribution(rng, samples);
        assertNotNull(dd);
    }

    @Test(expected = NotPositiveException.class)
    public void testDiscreteDistributionWithNegativeValue() throws Exception{
        List<Pair<String, Double>> samplesWithNegativeValue = new ArrayList<Pair<String, Double>>();
        samplesWithNegativeValue.add(new Pair<String, Double>("A", -0.2));
        samplesWithNegativeValue.add(new Pair<String, Double>("B", 0.3));
        DiscreteDistribution dd = new DiscreteDistribution(samplesWithNegativeValue);
    }

    @Test
    public void testSample() throws Exception{
        DiscreteDistribution dd = new DiscreteDistribution(samples);
        Object result = dd.sample();
        assertThat(result, anyOf(is("A"), is("B"), is("C")));
    }

