        DiscreteDistribution dd = new DiscreteDistribution(samples);
        assertEquals(0.2, dd.probability("A"), 1.0e-12);
        assertEquals(0.3, dd.probability("B"), 1.0e-12);
        assertEquals(0.5, dd.probability("C"), 1.0e-12);
    }

