    public void testGetSamples() throws Exception{
        List<Pair<String, Double>> samples = dist.getSamples();
        assertThat(samples.size(), equalTo(2));
    }

    @Test
    public void testProbability() throws Exception{
        double prob = dist.probability("A");
        assertThat(prob, equalTo(0.5));
    }

    @Test
    public void testResedRandomGenerator() throws Exception{
        long seed = 12345L;
        dist.reseedRandomGenerator(seed);
        // verify random generator was reseeded
    }

    @Test(expected=NotPositiveException.class)
    public void testDiscreteDistribution_NonPositiveProb() throws Exception{
        List<Pair<String, Double>> samples = new ArrayList<Pair<String, Double>>();
        samples.add(new Pair<String, Double>("A", -0.5));
        samples.add(new Pair<String, Double>("B", 0.5));
        new DiscreteDistribution(samples);
    }

