import org.junit.Test;
import org.junit.Assert;
import org.junit.Before;
import org.junit.After; 
import org.junit.Assert.*;
import org.junit.Ignore;
import org.junit.BeforeClass;
import org.junit.AfterClass;
import org.junit.runner.RunWith;
import org.junit.runners.JUnit4;
import org.junit.Rule;
import org.junit.rules.ExpectedException;
import org.mockito.Mockito.*
import static org.hamcrest.MatcherAssert.assertThat;
import static org.hamcrest.Matchers.*;
import java.io.Serializable;
import java.text.NumberFormat;
import java.util.Iterator;
import java.util.Comparator;
import java.util.TreeMap;

public class FrequencyTest{
private Frequency freq;

    @Before 
    public void init(){
        freq = new Frequency();
    }

    @Test 
    public void testAddValue_Comparable(){
        Integer[] values = {1,2,2,3,3,3};
        for (Integer value: values){
            freq.addValue(value);
        }
        assertEquals(6, freq.getSumFreq());
        assertEquals(1, freq.getCount(1));
        assertEquals(2, freq.getCount(2));
        assertEquals(3, freq.getCount(3));
    }

    @Test 
    public void testAddValue_Integer(){
        Integer[] values = {1,2,2,3,3,3};
        for (Integer value: values){
            freq.addValue(value);
        }
        assertEquals(6, freq.getSumFreq());
        assertEquals(1, freq.getCount(1));
        assertEquals(2, freq.getCount(2));
        assertEquals(3, freq.getCount(3));
    }

    @Test 
    public void testAddValue_Int(){
        int[] values = {1,2,2,3,3,3};
        for (int value: values){
            freq.addValue(value);
        }
        assertEquals(6, freq.getSumFreq());
        assertEquals(1, freq.getCount(1));
        assertEquals(2, freq.getCount(2));
        assertEquals(3, freq.getCount(3));
    }

    @Test 
    public void testAddValue_Long(){
        Long[] values = {1L,2L,2L,3L,3L,3L};
        for (Long value: values){
            freq.addValue(value);
        }
        assertEquals(6, freq.getSumFreq());
        assertEquals(1, freq.getCount(1L));
        assertEquals(2, freq.getCount(2L));
        assertEquals(3, freq.getCount(3L));
    }

    @Test 
    public void testAddValue_Char(){
        char[] values = {'a','b','b','c','c','c'};
        for (char value: values){
            freq.addValue(value);
        }
        assertEquals(6, freq.getSumFreq());
        assertEquals(1, freq.getCount('a'));
        assertEquals(2, freq.getCount('b'));
        assertEquals(3, freq.getCount('c'));
    }

    @Test 
    public void testAddValue_NotComparable(){
        try {
            freq.addValue(new Object());
            Assert.fail();
        } catch (IllegalArgumentException e) {}
    }

    @Test 
    public void testGetSumFreq(){
        Integer[] values = {1,2,2,3,3,3};
        for (Integer value: values){
            freq.addValue(value);
        }
        assertEquals(6, freq.getSumFreq());
    }

    @Test 
    public void testGetCount(){
        Integer[] values = {1,2,2,3,3,3};
        for (Integer value: values){
            freq.addValue(value);
        }
        assertEquals(1, freq.getCount(1));
        assertEquals(2, freq.getCount(2));
        assertEquals(3, freq.getCount(3));
        assertEquals(0, freq.getCount("abc"));
    }

    @Test 
    public void testGetPct(){
        Integer[] values = {1,2,2,3,3,3};
        for (Integer value: values){
            freq.addValue(value);
        }
        assertEquals(1./6., freq.getPct(1), 1e-6);
        assertEquals(2./6., freq.getPct(2), 1e-6);
        assertEquals(3./6., freq.getPct(3), 1e-6);
        assertEquals(0., freq.getPct("abc"), 1e-6);
    }

    @Test 
    public void testGetCumFreq(){
        Integer[] values = {1,2,2,3,3,3};
        for (Integer value: values){
            freq.addValue(value);
        }
        assertEquals(1, freq.getCumFreq(1));
        assertEquals(3, freq.getCumFreq(2));
        assertEquals(6, freq.getCumFreq(3));
        assertEquals(0, freq.getCumFreq("abc"));
    }

    @Test 
    public void testGetCumPct(){
        Integer[] values = {1,2,2,3,3,3};
        for (Integer value: values){
            freq.addValue(value);
        }
        assertEquals(1./6., freq.getCumPct(1), 1e-6);
        assertEquals(3./6., freq.getCumPct(2), 1e-6);
        assertEquals(1., freq.getCumPct(3), 1e-6);
        assertEquals(0., freq.getCumPct("abc"), 1e-6);
    }

    @Test 
    public void testClear(){
        Integer[] values = {1,2,2,3,3,3};
        for (Integer value: values){
            freq.addValue(value);
        }
        freq.clear();
        assertEquals(0, freq.getSumFreq());
    }

    @Test 
    public void testValuesIterator(){
        Integer[] values = {1,2,2,3,3,3};
        for (Integer value: values){
            freq.addValue(value);
        }
        Iterator iterator = freq.valuesIterator();
        int count = 0;
        while (iterator.hasNext()){
            Object o = iterator.next();
            if (o instanceof Long){
                count += (Long) o;
            }
        }
        assertEquals(6, count);
    }

    @Test 
    public void testToString(){
        Integer[] values = {1,2,2,3,3,3};
        for (Integer value: values){
            freq.addValue(value);
        }
        String str = freq.toString();
        assertNotNull(str);
    }
}
