    public void setUp() {
        frequency = new Frequency();
    }

    @Test
    public void testAddValue() {
        frequency.addValue(1L);
        Assert.assertEquals(1, frequency.getCount(1L));
    }

    @Test
    public void testAddValueMultipleTimes() {
        frequency.addValue(1L);
        frequency.addValue(1L);
        Assert.assertEquals(2, frequency.getCount(1L));
    }

    @Test
    public void testAddValueDifferentValues() {
        frequency.addValue(1L);
        frequency.addValue(2L);
        Assert.assertEquals(1, frequency.getCount(1L));
        Assert.assertEquals(1, frequency.getCount(2L));
    }

    @Test
    public void testGetCount() {
        frequency.addValue(1L);
        Assert.assertEquals(1, frequency.getCount(1L));
        Assert.assertEquals(0, frequency.getCount(2L));
    }

    @Test
    public void testGetSumFreq() {
        frequency.addValue(1L);
        frequency.addValue(2L);
        Assert.assertEquals(2, frequency.getSumFreq());
    }

    @Test
    public void testGetPct() {
        frequency.addValue(1L);
        frequency.addValue(1L);
        Assert.assertEquals(1.0 / 2.0, frequency.getPct(1L), 0.01);
    }

    @Test
    public void testGetCumFreq() {
        frequency.addValue(1L);
        frequency.addValue(1L);
        frequency.addValue(2L);
        Assert.assertEquals(2, frequency.getCumFreq(1L));
    }

    @Test
    public void testGetCumPct() {
        frequency.addValue(1L);
        frequency.addValue(1L);
        frequency.addValue(2L);
        Assert.assertEquals(2.0 / 3.0, frequency.getCumPct(1L), 0.01);
    }

    @Test
    public void testClear() {
        frequency.addValue(1L);
        frequency.clear();
        Assert.assertEquals(0, frequency.getCount(1L));
    }

    @Test
    public void testValuesIterator() {
        frequency.addValue(1L);
        Iterator iterator = frequency.valuesIterator();
        Assert.assertTrue(iterator.hasNext());
    }

    @Test
    public void testToString() {
        frequency.addValue(1L);
        Assert.assertNotNull(frequency.toString());
    }
}
