        Fraction f2 = new Fraction(1,2);
        assertEquals(0, f1.compareTo(f2));

        Fraction f3 = new Fraction(2,3);
        assertTrue(f1.compareTo(f3) < 0);

        Fraction f4 = new Fraction(1,3);
        assertTrue(f1.compareTo(f4) > 0);

        Fraction f5 = new Fraction(Integer.MAX_VALUE,Integer.MAX_VALUE);
        assertTrue(f1.compareTo(f5) < 0);

        Fraction f6 = new Fraction(-1,2);
        assertTrue(f1.compareTo(f6) > 0);
    }

