    public void testSolve_min_max_initial_not_in_interval() {
        ExpectedException expectedException = ExpectedException.none();
        expectedException.expect(IllegalArgumentException.class);
        expectedException.expectMessage("Initial guess is not in search interval");
        try {
            solver.solve(-1, 1, 2);
        } catch (Exception e) {
            throw expectedException;
        }
    }

    @Test 
    public void testSolve_min_max_initial_at_min() throws Exception {
        double result = solver.solve(-1, 1, -1);
        assertEquals(-1.0, result, 1e-6);
    }

