    public void testSolve_min_max_initial_almost_at_min() throws Exception {
        double result = solver.solve(-1, 1, -1 + 1e-12);
        assertEquals(-1.0, result, 1e-6);
    }

    @Test 
    public void testSolve_min_max_initial_almost_at_max() throws Exception {
        double result = solver.solve(-1, 1, 1 - 1e-12);
        assertEquals(1.0, result, 1e-6);
    }

    @Test 
    public void testSolve_min_max_max_iterations_exceeded() {
        UnivariateRealFunction f = mock(UnivariateRealFunction.class);
        when(f.value(anyDouble())).thenReturn(1.0);
        BrentSolver solver = new BrentSolver(f);
        ExpectedException expectedException = ExpectedException.none();
        expectedException.expect(MaxIterationsExceededException.class);
        try {
            solver.solve(-1, 1);
        } catch (Exception e) {
            throw expectedException;
        }
    }

